package vn.contractgovernance.api.files;
import java.util.*;
import java.sql.Timestamp;
import java.time.Clock;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
/** Files-owned finite disposition. Caller holds target locks and the exact committed reservation. */
@Service public class FileDispositions {
 private final EntityStore store;private final FileService files;private final PrivateBlobStore blobs;private final JsonSupport json;private final Clock clock;
 public FileDispositions(EntityStore store,FileService files,PrivateBlobStore blobs,JsonSupport json,Clock clock){this.store=store;this.files=files;this.blobs=blobs;this.json=json;this.clock=clock;}
 public JsonNode proof(EntityStore.Entity file){if(!file.body().path("state").asString().equals("CLEAN"))throw ApiException.of("FILE_NOT_CLEAN","Disposition cần exact CLEAN source.");var blob=files.blob(file.id());blobs.read(blob.key(),blob.hash());var p=json.object().put("fileId",file.id().toString()).put("version",file.version()).put("key",blob.key()).put("hash",blob.hash()).put("mediaType",file.body().path("mediaType").asString());if(blob.redactedKey()==null){p.putNull("redactedKey").putNull("redactedHash");}else{blobs.read(blob.redactedKey(),blob.redactedHash());p.put("redactedKey",blob.redactedKey()).put("redactedHash",blob.redactedHash());}return p;}
 public void logical(UUID request,EntityStore.Entity file,JsonNode record,JsonNode proof,UUID officer){store.jdbc().queryForObject("select set_config('cg.disposition_request',?,true)",String.class,request.toString());if(file.version()!=record.path("expectedRecordVersion").asInt())throw ApiException.of("BASE_CONFLICT","Disposition source version changed.");if(!proof(file).equals(proof.path("file")))throw ApiException.of("STORAGE_INTEGRITY","Disposition source bytes changed.");var b=(ObjectNode)file.body().deepCopy();String action=record.path("action").asString();if(action.equals("DELETE_BYTES")){b.put("state","DISPOSED").put("filename","disposed-"+file.id()).put("updatedAt",JsonSupport.timestamp(clock.instant()));store.jdbc().update("update cg_file_blob set storage_key=?,redacted_storage_key=null,redacted_sha256=null,redacted_media_type=null,redacted_verified_by=null where file_id=?",UUID.randomUUID().toString(),file.id());}else{var copy=proof.path("replacement");UUID copyId=UUID.fromString(copy.path("fileId").asString());var current=store.lock("File",copyId);if(current.version()!=copy.path("version").asInt()||!proof(current).equals(copy))throw ApiException.of("STORAGE_INTEGRITY","Reviewed safe copy differs.");store.jdbc().update("update cg_file_blob set redacted_storage_key=?,redacted_sha256=?,redacted_media_type=?,redacted_verified_by=? where file_id=?",copy.path("key").asString(),copy.path("hash").asString(),copy.path("mediaType").asString(),officer,file.id());if(action.equals("REDACT"))b.put("sensitive",true);b.put("updatedAt",JsonSupport.timestamp(clock.instant()));}var updated=store.update(file,b);store.jdbc().update("update cg_disposition_record set phase=?,result_version=? where request_id=? and record_id=? and phase='RESERVED'",action.equals("DELETE_BYTES")?"LOGICAL":"DONE",updated.version(),request,file.id());}
 public void cleanup(UUID request,UUID record){var rows=store.jdbc().query("select storage_key,expected_hash from cg_disposition_key where request_id=? and record_id=? order by storage_key",(rs,n)->List.of(rs.getString(1),rs.getString(2)),request,record);for(var row:rows)blobs.disposeCommitted(row.get(0),row.get(1),request,record);}
}
